using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Orthogonality;

internal sealed class SixDimensionalLiftGeometryDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Orthogonality/SixDimensionalLiftGeometry.";
    private static DocumentBlock Item(string id, string declaration, string title,
        string text, DescribeRole role) => Describe.Lean(DescribeId.Create(id),
        DeclarationHandle.Create(Prefix + declaration), H(title),
        StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(
            LibraryNoteRef.Create("D5/L/QuadraticForms/binarysubspace2026complete")),
        Blocks(Paragraph(Text(text))), role);

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Complete kernel/projection/placement geometry of the received orthogonality result.",
        H("Full actual submodules and source criteria"),
        Blocks(
            Item("coordinates", "coordinates", "The original fixed coordinate splitting",
                "The explicit linear equivalence sends the first summand to span(3,12,48) and the second to span(1,4,16).", DescribeRole.Definition),
            Item("coordinates-dot", "coordinates_dot", "The exact source pairing",
                "In these coordinates the actual standard pairing is t dot s-prime + s dot t-prime + s dot s-prime over F2.", DescribeRole.Theorem),
            Item("t", "T", "The specified isotropic space",
                "This is the actual image of the first coordinate summand.", DescribeRole.Definition),
            Item("s", "S", "The specified complement",
                "This is the actual image of the second coordinate summand.", DescribeRole.Definition),
            Item("t-source", "T_source", "The original T masks",
                "Prove the actual equality T=span(3,12,48), rather than selecting an unrelated isotropic space.", DescribeRole.Theorem),
            Item("s-source", "S_source", "The original S masks",
                "Prove the actual equality S=span(1,4,16), with the same bit ordering as the supplied catalogue.", DescribeRole.Theorem),
            Item("split", "split", "The actual inverse coordinate submodule",
                "Pull back the entire original U along the fixed linear equivalence; no vectors or subspaces are discarded.", DescribeRole.Definition),
            Item("kernel", "K", "The complete original intersection coordinates",
                "K is the first-kernel coordinate submodule and maps exactly onto U intersect T.", DescribeRole.Definition),
            Item("projection", "P", "The complete original projection",
                "P is the entire second-coordinate image, with its original domain retained.", DescribeRole.Definition),
            Item("annihilator", "H", "The complete original annihilator",
                "The perfect T/S pairing identifies H with the full P annihilator and with U-perp intersect T.", DescribeRole.Definition),
            Item("dimension-profile", "dimension_profile", "The complete dimension profile",
                "The actual dimension is dim(K)+dim(P). Thus the full source dimension/K/H profile is recovered from the exact K/P pair.", DescribeRole.Theorem),
            Item("k-source", "K_source", "Actual K equals U intersect T",
                "The exact first-kernel coordinates map onto the actual intersection U intersect T.", DescribeRole.Theorem),
            Item("h-source", "H_source", "Actual H equals U-perp intersect T",
                "The full projection annihilator maps onto the actual orthogonal intersection, for every coordinate submodule.", DescribeRole.Theorem),
            Item("projection-recovered", "projection_recovered", "Recover the full projection",
                "The perfect first-second pairing recovers P from its annihilator H, without losing placement information.", DescribeRole.Theorem),
            Item("profile-iff", "profile_iff", "Equivalent exact profile data",
                "Equality of the actual K/P pair is equivalent to equality of the full dimension/K/H profile. This is a profile equivalence and supplies no coloring rule.", DescribeRole.Theorem),
            Item("represented", "represented", "Actual submodule from full data",
                "Map the complete quotient-lift submodule through the fixed coordinate equivalence.", DescribeRole.Definition),
            Item("reconstruction", "reconstruction", "Every actual submodule is reconstructed",
                "All actual six-coordinate Submodules, including zero and the whole space, have unique full quotient placement data.", DescribeRole.Theorem),
            Item("orthogonal-iff", "orthogonal_iff", "The actual X/Y/Z test",
                "For every full pair of lift data, standard-coordinate orthogonality is equivalent to vanishing of both cross terms and the entire placement pairing. The representative lifts are arbitrary; no successful profile-only coloring rule is supplied.", DescribeRole.Theorem),
            Item("profile-card", "profile_card", "Exact number of full placements",
                "The entire actual K/P fiber has cardinality 2^(dim(P)*(3-dim(K))). Degenerate fibers remain included. The supplied 240/139 profile statistics are separate finite-certificate obligations.", DescribeRole.Theorem),
            Item("complement-kernel", "complement_kernel", "The actual intersection with S",
                "The pullback of every fully represented U along the original S embedding is exactly the subtype image of ker(f). This retains the actual projection domain and full quotient map.", DescribeRole.Theorem),
            Item("annihilator-dimension", "annihilator_dimension", "The complete annihilator dimension",
                "The full perfect pairing proves dim(H)=3-dim(P).", DescribeRole.Theorem),
            Item("projection-zero", "projection_eq_bot_iff", "Detect the complete fixed clique domain",
                "The actual full projection is zero exactly when U is contained in the original T.", DescribeRole.Theorem),
            Item("nonclique-annihilator-dimension", "nonclique_annihilator_dimension", "Exhaustive nonclique annihilator dimensions",
                "Every actual submodule outside T has annihilator dimension at most two; this is derived from the full object and is not a restricted input domain.", DescribeRole.Theorem),
            Item("label-card", "label_card", "All fifteen original labels",
                "The Gaussian count gives fifteen actual nonzero subspaces of the original three-dimensional T coordinate domain.", DescribeRole.Theorem),
            Item("allowed-label-card", "allowed_label_card", "Every allowed label is counted",
                "The complete allowed label set has cardinality 15-N(dim(H)). The already proved general contained-subspace count is reused directly.", DescribeRole.Theorem),
            Item("allowed-label-sizes", "allowed_label_sizes", "The exact source list sizes",
                "At annihilator dimensions zero, one and two the list sizes are respectively fifteen, fourteen and eleven. All nonclique vertices have one of these dimensions.", DescribeRole.Theorem),
            Item("label-vertex", "labelVertex", "Actual fixed-clique label vertices",
