            Item("precolor-criterion", "precolor_criterion", "The complete normalized-label equivalence",
                "For every assignment of the fifteen nonzero fixed-T subspaces, normalized on all clique vertices, proper coloring is equivalent to label availability and nonorthogonality of every distinct same-label nonclique pair. The preceding full X/Y/Z theorem supplies the coordinate test. This is a criterion for a candidate, not a new structural construction. The exact n7 values and paused case-exclusion work remain open.", DescribeRole.Theorem)),
        [DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/Combinatorics/Orthogonality/SixBitSubmoduleBridge")),
         DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/Combinatorics/Orthogonality/SplitSubmoduleLift")),
         DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/Combinatorics/Orthogonality/GaussianSubspaceCount")),
         DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/Combinatorics/Orthogonality/OrthogonalityDegreeDeletion"))]));
